const rows = $input.all();
if (rows.length === 0 || rows[0].json?.error) {
  return [{ json: { found: false, book: null } }];
}
const j = rows[0].json;
return [{
  json: {
    found: true,
    book: {
      id: j.id,
      title: j.title || '',
      author: j.author || '',
      description: j.description || null,
      isbn: j.isbn || null,
      coverUrl: j.coverUrl || null,
      price: j.price != null ? Number(j.price) : null,
      stock: j.stock != null ? Number(j.stock) : null,
      categories: Array.isArray(j.categories) ? j.categories.filter(Boolean) : []
    }
  }
}];
